namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidate(principal, resource, request, out var validationDecision))
            return validationDecision;

        var context = CreateAuthorizationContext(principal!, resource!, request!, delegations);

        if (TryEvaluateExceptionalAccess(principal!, resource!, request!, context, out var exceptionalDecision))
            return exceptionalDecision;

        if (TryEvaluateAction(request!, context, out var actionDecision))
            return actionDecision;

        return CreateSuccessfulDecision(resource!, request!, context.Delegated);
    }

    private static bool TryValidate(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (TryValidateContext(principal, resource, request, out decision))
            return true;
        if (TryValidateIdentityAndStatus(principal!, resource!, out decision))
            return true;

        return TryValidateRequestConstraints(principal!, resource!, request!, out decision);
    }

    private static bool TryValidateContext(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateIdentityAndStatus(
        Principal principal,
        Resource resource,
        out AccessDecision decision)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }
        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateRequestConstraints(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }
        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AuthorizationContext CreateAuthorizationContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AuthorizationContext(administrator, operatorRole, auditor, owner, delegated);
    }

    private static bool TryEvaluateExceptionalAccess(
        Principal principal,
        Resource resource,
        AccessRequest request,
        AuthorizationContext context,
        out AccessDecision decision)
    {
        if (TryEvaluateBreakGlass(request, context.Administrator, out decision))
            return true;

        return TryEvaluateRestrictedResource(resource, request, out decision);
    }

    private static bool TryEvaluateBreakGlass(
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryEvaluateRestrictedResource(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryEvaluateAction(
        AccessRequest request,
        AuthorizationContext context,
        out AccessDecision decision)
    {
        if (TryEvaluateDelete(request, context.Administrator, out decision))
            return true;
        if (TryEvaluateWrite(request, context, out decision))
            return true;
        if (TryEvaluateRead(request, context, out decision))
            return true;

        return TryEvaluateUnknownAction(request, out decision);
    }

    private static bool TryEvaluateDelete(
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (request.Action == "delete" && !administrator)
        {
            decision = new AccessDecision(false, "administrator-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryEvaluateWrite(
        AccessRequest request,
        AuthorizationContext context,
        out AccessDecision decision)
    {
        if (request.Action == "write" &&
            !(context.Administrator || context.OperatorRole || context.Owner || context.Delegated))
        {
            decision = new AccessDecision(false, "write-not-authorised", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryEvaluateRead(
        AccessRequest request,
        AuthorizationContext context,
        out AccessDecision decision)
    {
        if (request.Action == "read" &&
            !(context.Administrator || context.OperatorRole || context.Auditor || context.Owner || context.Delegated))
        {
            decision = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryEvaluateUnknownAction(AccessRequest request, out AccessDecision decision)
    {
        if (request.Action is not ("read" or "write" or "delete"))
        {
            decision = new AccessDecision(false, "unknown-action", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision CreateSuccessfulDecision(
        Resource resource,
        AccessRequest request,
        bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private readonly struct AuthorizationContext
    {
        public AuthorizationContext(
            bool administrator,
            bool operatorRole,
            bool auditor,
            bool owner,
            bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
    }
}
